1	import testGlobsInStep from './test-globs-in-step.mjs';
2	import verifyShSourceDirs from './verify-sh-source-dirs.mjs';
3	import noStrayPackageJson from './no-stray-package-json.mjs';
4	
5	// EdFringeNow's own local pack: project-specific working rules captured in this
6	// repo, layered on the shared Claudinite canon. Declaration-authoritative (no
7	// structural fingerprint). Its RULES.md is injected wherever this pack is declared,
8	// and its checks run against the tree.
9	export default {
10	  id: 'edfringe',
11	  ruleRoutingGuidance: {
12	    belongs: "EdFringeNow's own working rules — its build steps, shell scripts, and repo layout conventions",
13	    excludes: 'the edfringe.com scrape and the data layer it produces — those are edfringe-data',
14	  },
15	  detect: null,
16	  marker: null,
17	  prose: 'RULES.md',
18	  worldRules: [testGlobsInStep, verifyShSourceDirs, noStrayPackageJson],
19	};
20

1	// Dependency-free by design: a local pack's checks must load without the
2	// vendored mount, so this returns plain finding objects rather than importing
3	// engine/checks/helpers/findings.mjs.
4	
5	const VERIFY = 'scripts/verify.sh';
6	
7	// The `git ls-files 'js' 'plan' 'shared'` call in verify.sh's "JavaScript
8	// syntax" step — captures its quoted top-level-directory arguments.
9	const LS_FILES_DIRS = /git ls-files((?:\s+'[^']*')+)/;
10	const JS_FILE = /\.m?js$/;
11	
12	const rule = {
13	  id: 'edfringe-verify-sh-covers-source-dirs',
14	  severity: 'blocking',
15	  description:
16	    'scripts/verify.sh\'s JavaScript syntax-check step names every top-level directory that has committed .js/.mjs source',
17	  why:
18	    'the step only walks the top-level directories named in its `git ls-files` call; a source directory left off that list is silently never parse-checked, in the pre-commit hook or in CI',
19	  doc: 'RULES.md',
20	
21	  run(ctx) {
22	    const verifyRaw = ctx.read(VERIFY);
23	    if (verifyRaw === null) return []; // relevance-first: no gate script, nothing to check
24	
25	    const m = LS_FILES_DIRS.exec(verifyRaw);
26	    const listed = new Set((m ? m[1].match(/'([^']*)'/g) : []).map((s) => s.slice(1, -1)));
27	
28	    const present = new Set();
29	    for (const f of ctx.files) {
30	      if (!JS_FILE.test(f)) continue;
31	      const slash = f.indexOf('/');
32	      if (slash === -1) continue; // a bare top-level file, not inside a directory
33	      const top = f.slice(0, slash);
34	      if (top.startsWith('.')) continue; // hidden/tooling dirs (.claudinite, .github, ...) are out of scope
35	      present.add(top);
36	    }
37	
38	    const missing = [...present].filter((d) => !listed.has(d)).sort();
39	    if (missing.length === 0) return [];
40	
41	    const plural = missing.length > 1;
42	    return [finding(
43	      `${missing.join(', ')} ${plural ? 'have' : 'has'} committed .js/.mjs files but ${plural ? "aren't" : "isn't"} named in ${VERIFY}'s \`git ls-files\` syntax-check step`,
44	      `add ${missing.map((d) => `'${d}'`).join(' ')} to the \`git ls-files\` call in ${VERIFY} — or, if the directory is deliberately excluded (vendored/generated content), extend its grep -v filter instead`,
45	    )];
46	  },
47	};
48	
49	function finding(what, fix) {
50	  return {
51	    rule: rule.id,
52	    severity: rule.severity,
53	    file: VERIFY,
54	    line: null,
55	    what,
56	    why: rule.why,
57	    fix,
58	    doc: rule.doc,
59	  };
60	}
61	
62	export default rule;
