1	// Dependency-free by design: a local pack's checks must load without the
2	// vendored mount, so this returns plain finding objects rather than importing
3	// engine/checks/helpers/findings.mjs.
4	
5	const VERIFY = 'scripts/verify.sh';
6	const NORMALIZER = 'scraper/normalize.py';
7	const SELFTEST = '--selftest';
8	
9	// Scoped parse rather than a grep: verify.sh labels the step
10	// `step "Normalizer self-test — normalize.py --selftest"`, so a plain grep for
11	// the two tokens passes even after the real invocation is deleted — the label
12	// alone would satisfy it. Drop comment lines and the quoted argument of every
13	// `step` call, then look for a surviving command line.
14	function commandLines(sh) {
15	  return sh
16	    .split('\n')
17	    .filter((l) => !/^\s*#/.test(l))
18	    .map((l) => l.replace(/\bstep\s+(["'])(?:(?!\1).)*\1/g, ''))
19	    // A trailing comment can carry the tokens too (`node --check  # not normalize.py --selftest`).
20	    .map((l) => l.replace(/\s#.*$/, ''));
21	}
22	
23	const rule = {
24	  id: 'edfringe-normalizer-selftest-in-verify',
25	  severity: 'blocking',
26	  description: "scripts/verify.sh runs the normalizer's offline self-test (python3 scraper/normalize.py --selftest)",
27	  why:
28	    "the live edfringe API is unreachable from a session, so the normalizer self-test is the ONE transform check that runs offline — drop it from the gate and every scraper change ships with no verification at all, in a repo where nothing else can stand in for it",
29	  doc: 'RULES.md',
30	
31	  run(ctx) {
32	    // Relevance-first: no normalizer, or one with no self-test to run, is not
33	    // this rule's business.
34	    if (!ctx.files.includes(NORMALIZER)) return [];
35	    const normalizer = ctx.read(NORMALIZER);
36	    if (normalizer === null || !normalizer.includes(SELFTEST)) return [];
37	
38	    const sh = ctx.files.includes(VERIFY) ? ctx.read(VERIFY) : null;
39	    if (sh === null) return []; // relevance-first: no verification gate in this tree
40	
41	    const wired = commandLines(sh).some((l) => l.includes('normalize.py') && l.includes(SELFTEST));
42	    if (wired) return [];
43	
44	    return [{
45	      rule: rule.id,
46	      severity: rule.severity,
47	      file: VERIFY,
48	      line: null,
49	      what: `${NORMALIZER} supports ${SELFTEST} but ${VERIFY} never invokes it (a step label naming it does not count — only a command line does)`,
50	      why: rule.why,
51	      fix: `restore the step to ${VERIFY}: \`python3 ${NORMALIZER} ${SELFTEST}\` — both the pre-commit hook and CI run that script, so this is the only place wiring it makes it a gate`,
52	      doc: rule.doc,
53	    }];
54	  },
55	};
56	
57	export default rule;
