1	// Red-first fixture for this pack's check, plus a guard on the pack manifest.
2	//
3	// The check reads its files through the engine's `ctx`, so the fixtures here are
4	// tiny in-memory contexts ({ files, read }) — no temp dirs, no mount, and the
5	// same shape the real runner passes (engine/checks/helpers/repo-context.mjs).
6	// The last test runs the rule against this repo's ACTUAL committed data, which
7	// is what makes the check a live gate rather than a self-fulfilling unit test.
8	
9	import { test } from "node:test";
10	import assert from "node:assert/strict";
11	import { readFileSync, existsSync } from "node:fs";
12	import { execFileSync } from "node:child_process";
13	import { fileURLToPath } from "node:url";
14	import path from "node:path";
15	
16	import pack from "./pack.mjs";
17	import rule from "./lookup-indices.mjs";
18	import selftestRule from "./normalizer-selftest-in-verify.mjs";
19	import dataDirRule from "./data-dir-is-generator-output.mjs";
