21	const __dirname = path.dirname(fileURLToPath(import.meta.url));
22	const REPO = path.resolve(__dirname, "../../../..");
23	
24	/** A context over an in-memory {path: string} map, for the text-reading checks. */
25	function textCtx(tree) {
26	  const files = Object.keys(tree);
27	  return { files, read: (p) => (p in tree ? tree[p] : null) };
28	}
29	
30	/** A context over real files on disk, for the live-gate tests. */
31	function diskCtx(paths) {
32	  const present = paths.filter((f) => existsSync(path.join(REPO, f)));
33	  return {
34	    present,
35	    ctx: {
36	      files: present,
37	      read: (p) => (present.includes(p) ? readFileSync(path.join(REPO, p), "utf8") : null),
38	    },
39	  };
40	}
