42	const LOOKUPS = {
43	  venues: { "33": { name: "Pleasance Courtyard" } },
44	  rooms: ["Above", "Below"],
45	  genres: ["Comedy", "Theatre"],
46	  subgenres: ["Improv", "Stand-up"],
47	  ticketStatuses: ["SOLD_OUT", "TICKETS_AVAILABLE"],
48	  ageRestrictions: ["EIGHTEEN", "SIXTEEN"],
49	};
50	
51	/** A context over an in-memory {path: object} map, matching the engine's ctx. */
52	function ctxOf(tree) {
53	  const files = Object.keys(tree);
54	  return {
55	    files,
56	    read: (p) => (p in tree ? JSON.stringify(tree[p]) : null),
57	  };
58	}
