60	const cleanDay = [
61	  { id: "X", title: "A show", genre: 1, subs: [0, 1], venue: "33", room: 0, ts: 1 },
62	  // -1 is the producer's "unknown" for room and ticket status (normalize.py), not
63	  // an out-of-range index — the check must stay quiet on it.
64	  { id: "Y", title: "Another", genre: 0, subs: [], venue: "33", room: -1, ts: -1 },
