130	
131	test("no data layer in the tree ⇒ no findings (relevance-first)", () => {
132	  assert.deepEqual(rule.run(ctxOf({ "README.md": {} })), []);
133	});
134	
135	test("this repo's committed data satisfies the invariant", () => {
136	  // The live gate: every real day file plus the master, read off disk.
137	  const tree = ["data/venues.json", "data/normalized/shows.min.json"];
138	  const days = readFileSync(path.join(REPO, "data/days/index.json"), "utf8");
139	  for (const d of JSON.parse(days).dates) tree.push(`data/days/${d}.json`);
140	  const present = tree.filter((f) => existsSync(path.join(REPO, f)));
141	  assert.ok(present.length > 2, "expected the committed day files to be present");
142	
143	  const out = rule.run({
144	    files: present,
145	    read: (p) => (present.includes(p) ? readFileSync(path.join(REPO, p), "utf8") : null),
146	  });
147	  assert.deepEqual(out, [], `committed data violates the lookup-index contract:\n${
148	    out.map((f) => `${f.file}: ${f.what}`).join("\n")}`);
149	});
