151	// --- normalizer-selftest-in-verify: the one offline transform check must stay
152	// wired into scripts/verify.sh ---
153	
154	const NORMALIZER_PY = `import sys\nif "--selftest" in sys.argv:\n    run_selftest()\n`;
155	
156	const verifyWithSelftest = `#!/usr/bin/env bash
157	set -euo pipefail
158	
159	step "Normalizer self-test — normalize.py --selftest"
160	if command -v python3 >/dev/null 2>&1; then
161	  python3 scraper/normalize.py --selftest
162	fi
163	`;
164	
165	// The label survives; the invocation is gone. A grep for the two tokens passes
166	// here — which is precisely why the check strips `step "..."` before looking.
167	const verifyLabelOnly = `#!/usr/bin/env bash
168	set -euo pipefail
169	
170	step "Normalizer self-test — normalize.py --selftest"
171	echo "skipped"
172	`;
173	
174	test("verify.sh invoking the self-test ⇒ no findings", () => {
175	  const out = selftestRule.run(textCtx({
176	    "scraper/normalize.py": NORMALIZER_PY,
177	    "scripts/verify.sh": verifyWithSelftest,
178	  }));
179	  assert.deepEqual(out, [], `expected no findings, got ${JSON.stringify(out, null, 2)}`);
180	});
181	
182	test("a verify.sh left with only the step label is reported", () => {
183	  // The exact regression this guards: the step is gutted, the heading stays, and
184	  // the only offline verification a scraper change can get silently disappears.
185	  const out = selftestRule.run(textCtx({
186	    "scraper/normalize.py": NORMALIZER_PY,
187	    "scripts/verify.sh": verifyLabelOnly,
188	  }));
189	  assert.equal(out.length, 1);
190	  assert.equal(out[0].rule, "edfringe-normalizer-selftest-in-verify");
191	  assert.equal(out[0].severity, "blocking");
192	  assert.equal(out[0].file, "scripts/verify.sh");
193	  assert.match(out[0].what, /never invokes it/);
194	  assert.ok(out[0].fix.includes("--selftest"), "the fix must name the command to restore");
195	});
196	
197	test("a commented-out invocation does not count as wired", () => {
198	  const out = selftestRule.run(textCtx({
199	    "scraper/normalize.py": NORMALIZER_PY,
200	    "scripts/verify.sh": `#!/usr/bin/env bash\n# python3 scraper/normalize.py --selftest\necho hi\n`,
201	  }));
202	  assert.equal(out.length, 1);
203	});
