205	test("a trailing comment naming the command does not count as wired", () => {
206	  const out = selftestRule.run(textCtx({
207	    "scraper/normalize.py": NORMALIZER_PY,
208	    "scripts/verify.sh": `#!/usr/bin/env bash\nnode --check js/app.js  # unlike normalize.py --selftest, this is syntax only\n`,
